"""Scoped early Campaign3 claim review, retaining original occurrence identities."""
from pathlib import Path
from fractions import Fraction as F
import json,hashlib,copy
P=Path('docs/planning');B=P/'campaign3-history-universe-rev1';O=P/'campaign3-history-ledger-biology-rev1';O.mkdir(exist_ok=True)
SOURCE='docs/planning/VERDICT_LEDGER.md'
def sha(p):return hashlib.sha256(Path(p).read_bytes()).hexdigest()
def load(p):return json.loads(Path(p).read_text(encoding='utf-8-sig'))
def save(p,v):
 if p.exists():assert load(p)==v,p
 else:p.write_text(json.dumps(v,ensure_ascii=False,indent=2)+'\n',encoding='utf-8',newline='\n')
specs=[(2136, 'FEAR-GUILT', 'Innocent nervousness can mislead guilt attribution; admitted context revises it.', 'ContextOdds weights are not calibrated causal likelihoods; no enacted response or guilt detection.', ['CAMPAIGN3_FEAR_GUILT_QUALIFICATION.md']), (2150, 'PERSON-GOAL', 'Route/outcome evidence supports goal inference, including failed attempts; shared routes need not mean shared goals.', 'Fixed catalogue and factors not learned affordances or independent likelihoods; no observer action.', ['CAMPAIGN3_PERSON_GOAL_QUALIFICATION.md']), (2166, 'HEARSAY', 'Channel-labelled testimony/direct perception remain separate, with visible ticket dedup and valid delayed first receipt.', 'Direct perception can be wrong; no learned trust, independent corroboration, chosen speech or global reputation.', ['CAMPAIGN3_HEARSAY_QUALIFICATION.md']), (2181, 'REL-DIMENSIONS', 'Independent histories discriminate affection/respect/trust/comfort and prospective response distributions.', '7/9 versus2/9 are prospective probabilities, not sampled/executed behavior. Initial assumptions preserved; no universal dimension law.', ['CAMPAIGN3_REL_DIMENSIONS_QUALIFICATION.md']), (2198, 'REL-ATTRIBUTION', 'Event-linked false explanation changes caution without erasing harm; current willingness changes a separate probe.', 'Not enacted behavior, verified cause, calibrated blame, forgiveness or relationship repair.', ['CAMPAIGN3_REL_ATTRIBUTION_QUALIFICATION.md']), (2214, 'RELIANCE', 'Commitment history changes estimate and entrust probability; missing opportunity differs from failure and unknown from mixed evidence.', 'Equal distribution is not equal knowledge; no enacted delegation. Timeout/unexecuted plan retained.', ['CAMPAIGN3_RELIANCE_HISTORY_QUALIFICATION.md']), (2231, 'FAMILIAR-VALENCE', 'Matched familiarity with different outcome histories yields different signed appraisal; appearance does not transfer identity/history.', 'Not enacted interaction, general liking or attachment; TruthValence violates epistemic boundary.', ['CAMPAIGN3_FAMILIAR_VALENCE_QUALIFICATION.md']), (2247, 'ATTACHMENT', 'Meaningful dependence supports reconnection response despite adequate alternatives or absent current demand.', 'Mean contradiction resistance retained; not authored attachment meter, enacted search, physiological distress or universal counting law.', ['CAMPAIGN3_ATTACHMENT_QUALIFICATION.md']), (2263, 'BETRAYAL', 'Prior promise, experienced failure and incident intent/control differ from present willingness.', 'Late/simultaneous promise cannot become prior commitment; corrected prospective modifier is not repair or restored cooperation.', ['CAMPAIGN3_BETRAYAL_QUALIFICATION.md']), (2281, 'GRIEF', 'Believed future-contact loss changes appraisal at matched absence/history; substitute need not erase loss.', 'Missing report not known uncertainty/no contact; no clinical course, physical death or enacted mourning.', ['CAMPAIGN3_GRIEF_QUALIFICATION.md']), (2299, 'PERFORMANCE', 'Repeated admitted failure changes later plan and actual attempt; false feedback can prompt switch after success.', 'Blocker-removal confounds improvement; no proved superior alternative, causal diagnosis or universal threshold.', ['CAMPAIGN3_PERFORMANCE_QUALIFICATION.md']), (2314, 'RUMINATION', 'Recurrent access occupies workspace and changes control without new evidence; interruption/rebound/resolution preserve history.', '22 distinct runs/198 prefixes versus23 executions/207 checks due to duplicate, not extra coverage. No clinical recurrence or chosen regulation.', ['CAMPAIGN3_RUMINATION_QUALIFICATION.md']), (2330, 'FATIGUE', 'Experienced condition impairs inhibition separately from motor failure; missing evidence persists until admitted rest.', 'Unknown not rested; no endogenous accumulation or universal resource law.', ['CAMPAIGN3_FATIGUE_QUALIFICATION.md']), (2345, 'PROCRASTINATION', 'Positive work reason survives actual defer choice; access, feasibility, immediate motive and lifecycle remain distinct.', 'Available later does not establish sufficient completion capacity. Original0.1 missed late adoption;0.2 rejects at/after deadline.', ['CAMPAIGN3_PROCRASTINATION_QUALIFICATION.md']), (2361, 'DELAYED', 'Actual wait/choice, physical promise delivery and learned receipt differ; three discount candidates retained.', 'Not calibrated discount/trust/cross-benefit exchange or later adaptive choice; rejected schema preserved.', ['CAMPAIGN3_DELAYED_QUALIFICATION.md']), (2376, 'INTENTION', 'Reminder recovers surviving action content, not removed content; adopted goal/access/opportunity differ.', 'Component only, no public save API; failed zero-score recall assertion and identity successor preserve original behavior.', ['CAMPAIGN3_INTENTION_QUALIFICATION.md']), (2389, 'TEMPORAL', 'Losing goal survives contested choice for later pursuit; cancellation/expiry selective.', 'NoTemporalBias shares primary choices despite probability change; two faulty lifecycle comparators coincide, not unique diagnosis. Component only.', ['CAMPAIGN3_TEMPORAL_QUALIFICATION.md']), (2404, 'HABIT-RESIST', 'Existing frozen CONTROL runs support habit resistance clause without new behavior/model.', 'Separate FATIGUE qualification is not joint model or universal control. Stale family omission corrected only for named clause.', ['CAMPAIGN3_HABIT_RESISTANCE_QUALIFICATION.md']), (2419, 'HABIT-ACQUIRE', 'Admitted practice supports actual later free cue response after expectation correction.', 'Initial wrapper assumed nonexistent RunIdentity field; correction does not alter old commitments. Not automaticity/addiction/history reduction.', ['CAMPAIGN3_HABIT_ACQUISITION_QUALIFICATION.md']), (2436, 'SUBSTITUTION', 'Diversified training or information supports actual alternative relief after loss of A.', 'ExpectationOnly also explains primary witness; history not necessary there. NoActiveReasons at zero estimates gives no action. Both failed cohorts retained.', ['CAMPAIGN3_SUBSTITUTION_QUALIFICATION.md']), (2456, 'REINFORCEMENT', 'Admitted chosen outcomes change belief, later reasons and later action; withholding receipt breaks learning despite delivery.', 'Six sequence divergences/two equal; no monotonic repetition or objective reward escalation. LatestHistory serious; no new habit die.', ['CAMPAIGN3_REINFORCEMENT_QUALIFICATION.md']), (2475, 'TOLERANCE', 'Exposure changes tolerance and equal later stimulus has attenuated physical potential effect.', 'Prior R0+D was not effect consumer. World component, not perceived tolerance/recovery/public integration or universal law.', ['CAMPAIGN3_TOLERANCE_QUALIFICATION.md']), (2491, 'ABSENCE', 'Acquired reference displacement creates excess absence deficit; support removes gap without erasing adaptation.', 'Not subjective distress, recovery or action. Wrong-reference and build failures preserved; no public consumer.', ['CAMPAIGN3_ABSENCE_DEFICIT_QUALIFICATION.md']), (2507, 'CRAVING', 'Pressure and learned relief yield urge distinct from cue access, availability and restraint.', '56 identities/60 comparisons/280 distinct component prefixes not60 unique; aliases not salted. No action/earned control or relapse.', ['CAMPAIGN3_CRAVING_QUALIFICATION.md']), (2524, 'RELAPSE', 'Actual return under load in seeds1/7 after withholding; all resume withholding afterward.', 'Transient lapse, not sustained relapse/population rate or physiological recovery. Buffer rejection and same-identity successor retained.', ['CAMPAIGN3_RELAPSE_QUALIFICATION.md']), (2542, 'COSTLY-REWARD', 'Learned benefit/harm compete under maintained protection;7/8 repeat under load, all restore withholding.', 'Feedback not pathwise harm reducing; primary repetition not habit necessity. Preserve99 exploration trajectories; not full biology/public admission.', ['CAMPAIGN3_COSTLY_REWARD_QUALIFICATION.md']), (2560, 'BIOLOGY', '18 work-order behaviors integrate continuous body, safe sensing, learned pleasure/relief/harm, goals/control, actual effects and delayed stress.', '53 distinct runs/2389 prefixes versus54 execution rows/2438 checks; distinct domains not proven irreducible/calibrated. Component only.', ['CAMPAIGN3_BIOLOGICAL_SYSTEM_QUALIFICATION.md']), (2582, 'BIOLOGY-PUBLIC', 'Typed sources and disjoint owners reproduce53 component trajectories; intent70/expression80/sensing120/adaptation140.', '58 distinct runs/270 unique prefixes versus59 rows/273 checks; redundant writer excluded. Large-save byte failure retained. No general forecasting, clinical biology or Addicted trait.', ['CAMPAIGN3_BIOLOGY_PUBLIC_QUALIFICATION.md'])]

rows=[]
with (B/'units.jsonl').open(encoding='utf-8') as f:
 for line in f:
  u=json.loads(line)
  if u['source']!=SOURCE or not 2136<=u['location']['startLine']<=2608:continue
  assert u['location']['endLine']<=2608
  _,name,claim,limits,paths=max((s for s in specs if s[0]<=u['location']['startLine']),key=lambda s:s[0])
  rows.append(dict(occurrenceId=u['id'],location=u['location'],text=u['text'],claim=name,disposition=claim,limits=limits,evidence=paths))
raw=(B/'sources'/SOURCE).read_bytes();assert Path(SOURCE).read_bytes().startswith(raw)
lines=raw.decode('utf-8-sig').splitlines(keepends=True)
for r in rows:assert ''.join(lines[r['location']['startLine']-1:r['location']['endLine']])==r['text']
assert {n for r in rows for n in range(r['location']['startLine'],r['location']['endLine']+1)}=={n for n in range(2136,2609) if lines[n-1].strip()}
evidence=[]
for n in sorted({n for s in specs for n in s[4]}):
 p=P/n;evidence.append(dict(path=p.as_posix(),sha256=sha(p)))
v=dict(status='HQ011 DEPENDENCE AND BIOLOGY CLAIMS REVIEWED; WIDER AUDIT OPEN',source=dict(path=SOURCE,frozenSha256=sha(B/'sources'/SOURCE)),rows=rows,evidence=evidence,obligations=['RO-C3-001','RO-C3-005','RO-C3-006','RO-C3-007','RO-C3-008','RO-C3-009','RO-C3-010','RO-C3-011','RO-C3-012','RO-C3-013','RO-C3-014','RO-C3-015','RO-C3-016','RO-C3-017','RO-C3-019','RO-C3-020','RO-C3-021'],limits=['No fresh production simulation, test suite or build. Receipt bindings do not assert current source freshness for every old receipt.','Twenty-eight reviewed claim groups retain independent public/component, law and historical correction scopes.'],nextGate='Ledger2609 onward: identity, development and residual coverage.')
save(O/'review.json',v)
c=dict(status=v['status'],originalOccurrences=len(rows),claimGroups=len(specs),indexedWholeOccurrenceLinks=760+len(rows),freshBehavioralTests=0,reviewSha256=sha(O/'review.json'),checkerSha256=sha(__file__))
save(O/'check.json',c);print(json.dumps(c))
